<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {useCoffee} from '../stores/coffee';import type {Product,CartLine} from '../../../../packages/shared/src/types';import {money,calculateLine,totalCart,stateLabels} from '../../../../packages/shared/src/domain';import ProductPhoto from '../components/ProductPhoto.vue';import ProductOptions from '../components/ProductOptions.vue';import Modal from '../../../../packages/ui/src/Modal.vue';import Icon from '../components/Icon.vue';
const route=useRoute();const s=useCoffee();const table=computed(()=>s.state.tables.find(t=>t.token===route.params.token&&t.active));const branch=computed(()=>s.state.branches.find(b=>b.id===table.value?.branchId));const category=ref('all');const search=ref('');const selected=ref<Product>();const cart=ref<CartLine[]>([]);const cartOpen=ref(false);const tab=ref('menu');const customerKey='coffee-pos:customer-orders:'+String(route.params.token);const initialOrders=()=>{try{return JSON.parse(localStorage.getItem(customerKey)??'[]') as string[]}catch{return []}};const submitted=ref<string[]>(initialOrders());const busy=ref(false);const key=ref(crypto.randomUUID());
const products=computed(()=>s.state.products.filter(p=>p.active&&(category.value==='all'||p.category===category.value)&&p.name.toLowerCase().includes(search.value.toLowerCase())));
const priced=computed(()=>cart.value.map(l=>calculateLine(s.state.products.find(p=>p.id===l.productId)!,l)));const total=computed(()=>totalCart(priced.value));const ownOrders=computed(()=>s.state.orders.filter(o=>submitted.value.includes(o.id)));const count=computed(()=>cart.value.reduce((n,l)=>n+l.quantity,0));
function add(line:CartLine){cart.value.push(line);s.notify('Đã thêm món vào giỏ.')}
function quick(p:Product){cart.value.push({productId:p.id,quantity:1,variantId:p.variants[0].id,optionIds:[],note:''})}
function submit(){if(!table.value||!cart.value.length||busy.value)return;busy.value=true;const order=s.run(()=>s.repo.createOrder(table.value!.branchId,table.value!.id,cart.value,'qr',key.value),'Đơn đã lưu trên trình duyệt; chưa gửi tới quán.');if(order){submitted.value.push(order.id);try{localStorage.setItem(customerKey,JSON.stringify(submitted.value))}catch{s.notify('Đơn đã lưu, nhưng không thể lưu bộ lọc theo dõi trên trình duyệt.','error')}key.value=crypto.randomUUID();cart.value=[];cartOpen.value=false;tab.value='status'}busy.value=false}
function call(kind:string){if(table.value)s.run(()=>s.repo.requestCall(table.value!.id,kind),'Đã lưu yêu cầu trên trình duyệt; chưa gửi tới nhân viên.')}
</script><template><div v-if="table&&branch" class="customer-page"><header class="customer-header"><div class="customer-logo"><Icon name="coffee" :size="27"/><strong>{{s.state.settings.name}}</strong></div><div class="customer-table"><Icon name="table" :size="16"/>{{table.name}}</div></header><section class="customer-welcome"><p>{{branch.name}} · Chào bạn</p><h1>Một chút cà phê,<br>một ngày thật nhẹ.</h1><p>Chọn món bạn thích. Chúng mình pha theo cách của bạn.</p></section><div class="customer-tabs"><button :class="{selected:tab==='menu'}" @click="tab='menu'">Thực đơn</button><button :class="{selected:tab==='status'}" @click="tab='status'">Món đã gọi <span>{{ownOrders.length}}</span></button></div><template v-if="tab==='menu'"><label class="search-field"><Icon name="search"/><input v-model="search" placeholder="Bạn muốn uống gì?" aria-label="Tìm món trong menu"></label><div class="category-tabs"><button :class="{selected:category==='all'}" @click="category='all'">Tất cả</button><button v-for="c in s.state.categories" :key="c.id" :class="{selected:category===c.id}" @click="category=c.id">{{c.name}}</button></div><div class="customer-products"><article v-for="p in products" :key="p.id" :class="{unavailable:!p.available}"><button :aria-label="'Xem '+p.name" :disabled="!p.available" @click="selected=p"><ProductPhoto :photo="p.photo" :image="p.image" :name="p.name"/></button><div><h2>{{p.name}}</h2><p>{{p.description}}</p><footer><strong>{{money(p.price)}}</strong><button class="add-button" :aria-label="'Thêm '+p.name" :disabled="!p.available" @click="quick(p)"><Icon name="plus" :size="18"/></button></footer><small v-if="!p.available">Hết hàng</small></div></article></div></template><template v-else><div v-for="o in ownOrders" :key="o.id" class="panel customer-order"><header><strong>{{o.number}}</strong><span class="status" :class="o.state">{{stateLabels[o.state]}}</span></header><p v-for="l in o.lines" :key="l.id">{{l.quantity}} × {{l.name}} <small>{{l.note}}</small></p><b>{{money(o.total)}}</b></div><div v-if="!ownOrders.length" class="empty"><Icon name="coffee" :size="36"/><h3>Bạn chưa gọi món</h3><p>Chọn đồ uống yêu thích trong thực đơn.</p><button class="btn primary" @click="tab='menu'">Xem thực đơn</button></div></template><div class="customer-service"><button v-if="s.state.settings.allowCalls" class="btn outline" @click="call('Gọi nhân viên')"><Icon name="staff" :size="17"/>Gọi nhân viên</button><button v-if="s.state.settings.allowPaymentRequests" class="btn outline" @click="call('Yêu cầu thanh toán')"><Icon name="receipt" :size="17"/>Yêu cầu bill</button></div><footer class="customer-footer">Mỗi món được chuẩn bị với sự chăm chút.<small>{{branch.address}}</small></footer><button v-if="cart.length" class="customer-cart" @click="cartOpen=true"><span><b>{{count}}</b>Giỏ món của bạn</span><strong>{{money(total)}}</strong><Icon name="next"/></button></div><div v-else class="invalid-qr"><Icon name="table" :size="44"/><h1>QR bàn không còn khả dụng</h1><p>Nhờ nhân viên cung cấp mã QR mới hoặc kiểm tra bàn trong ứng dụng.</p><RouterLink to="/tables" class="btn primary">Xem bàn</RouterLink></div><ProductOptions v-if="selected" :product="selected" @close="selected=undefined" @add="add"/><Modal v-if="cartOpen" title="Giỏ món của bạn" @close="cartOpen=false"><div v-for="(l,i) in priced" :key="i" class="list-row"><span>{{l.name}}<small>{{l.variant}} · {{l.note}}</small></span><div class="stepper"><button :aria-label="'Giảm '+l.name" @click="cart[i].quantity>1?cart[i].quantity--:cart.splice(i,1)">−</button><span>{{l.quantity}}</span><button :aria-label="'Tăng '+l.name" @click="cart[i].quantity=Math.min(99,cart[i].quantity+1)">+</button></div><b>{{money(l.total)}}</b></div><div class="total-row grand-total"><strong>Tổng cộng</strong><strong>{{money(total)}}</strong></div><p class="muted small-copy">Món sẽ ở trạng thái chờ nhân viên xác nhận. Bản xem này lưu riêng trên từng trình duyệt.</p><button class="btn primary full" :disabled="!cart.length||busy" @click="submit">{{busy?'Đang lưu...':'Gửi đơn gọi món'}}</button></Modal></template>
